import math
def feature_matrix(rows,schema):
    if len(set(schema))!=len(schema):raise ValueError('duplicate feature')
    result=[]
    for row in rows:
        if set(row)!=set(schema):raise ValueError('schema mismatch')
        values=[row[k] for k in schema]
        if any(type(x) not in (int,float) or not math.isfinite(x) for x in values):raise ValueError('invalid numeric feature')
        result.append([float(x) for x in values])
    return result

