def rotated_importance(predict,rows,targets,column):
    if not rows or len(rows)!=len(targets) or type(column) is not int or column<0 or any(column>=len(row) for row in rows):raise ValueError('invalid data')
    changed=[list(row) for row in rows]
    for i,row in enumerate(changed):row[column]=rows[(i+1)%len(rows)][column]
    def loss(data):
        values=list(predict(data))
        if len(values)!=len(targets):raise ValueError('prediction length')
        return sum((p-y)**2 for p,y in zip(values,targets))/len(targets)
    return loss(changed)-loss(rows)

