import math
def promotion_reasons(candidate,min_gain,max_p95,max_cost):
    keys=['gain','p95_ms','cost']
    if any(k not in candidate or not isinstance(candidate[k],(int,float)) or not math.isfinite(candidate[k]) for k in keys):return ['invalid evidence']
    if candidate['p95_ms']<0 or candidate['cost']<0:return ['invalid evidence']
    reasons=[]
    if candidate['gain']<min_gain:reasons.append('quality')
    if candidate['p95_ms']>max_p95:reasons.append('latency')
    if candidate['cost']>max_cost:reasons.append('cost')
    return reasons

def budget_batches(sizes,capacity):
    if type(capacity) is not int or capacity<1 or any(type(x) is not int or x<1 or x>capacity for x in sizes):raise ValueError('invalid capacity')
    result=[];batch=[];used=0
    for i,size in enumerate(sizes):
        if batch and used+size>capacity:result.append(batch);batch=[];used=0
        batch.append(i);used+=size
    if batch:result.append(batch)
    return result

